actionConfiguration.body:
select *
from public.save_recipe(
	'{{ appsmith.user.email }}',
	{{ Number(appsmith.store.current_recipe_id || 0) || null }},
	'{{ appsmith.store.current_client_id }}'::uuid,
	'{{ JSON.stringify(jsRecSave.headerPayload()).replaceAll("'", "''") }}'::jsonb,
	'{{ JSON.stringify(jsRecSave.dietTagsPayload()).replaceAll("'", "''") }}'::jsonb,
	'{{ JSON.stringify(jsRecSave.componentsPayload()).replaceAll("'", "''") }}'::jsonb,
	{{ appsmith.store.recipe_unit_change_confirmed === true }}
);
